(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5434],{85910:function(a,e,i){Promise.resolve().then(i.bind(i,78737))},78737:function(a,e,i){"use strict";i.r(e),i.d(e,{default:function(){return o}});var r=i(3827);i(64090);var n=i(31725);let l={updatedAt:"2026-06-16",articleHeadline:"Trendyol K\xe2r Hesaplama: Komisyon, KDV, Stopaj ve Platform Bedeli Dahil Net K\xe2r Rehberi",articleDescription:"Trendyol satıcıları i\xe7in komisyon, kargo, platform hizmet bedeli, KDV ve stopaj dahil net k\xe2r hesaplama rehberi; g\xfcncel 2026 oranları ve adım adım işlenmiş \xf6rnek.",blocks:[{type:"prose",heading:"Trendyol’da Net K\xe2r Nasıl Hesaplanır?",paragraphs:["Trendyol’da bir \xfcr\xfcn\xfc 299 TL’ye satmak, cebinize 299 TL girdiği anlamına gelmez. Satış fiyatının i\xe7inden komisyon, platform hizmet bedeli, kargo, KDV ve stopaj gibi kalemler d\xfcş\xfcl\xfcr; geriye kalan tutardan da \xfcr\xfcn\xfcn maliyetini \xe7ıkardığınızda elinizde ger\xe7ek kazancınız olan net k\xe2r kalır. Bir\xe7ok satıcı ciroyu k\xe2rla karıştırır ve aslında zarar ettiği \xfcr\xfcnleri yıllarca satmaya devam eder.","Net k\xe2r, ekonomik kazancınızdır: bir siparişten elde ettiğiniz ciro ile o siparişi ger\xe7ekleştirmek i\xe7in katlandığınız t\xfcm maliyetlerin farkı. Bu sayfadaki hesaplayıcı her kalemi tek tek ayırarak g\xf6sterir; aşağıdaki rehber ise hangi kesintinin neyi temsil ettiğini, hangi rakamların nereden geldiğini ve k\xe2rınızı en \xe7ok hangi kalemlerin aşındırdığını anlatır."]},{type:"feeTable",heading:"Trendyol Kesinti Kalemleri (2026)",intro:"Aşağıdaki tablo bir Trendyol satışından d\xfcş\xfclen başlıca kalemleri \xf6zetler. Komisyon oranı kategoriye ve kampanyaya g\xf6re değiştiği i\xe7in sabit bir oran yerine aralık verilmiştir.",columns:["Kalem","Oran / Tutar","A\xe7ıklama"],rows:[["Komisyon","Kategoriye g\xf6re %5 – %25","Satış tutarı \xfczerinden alınır; kategoriye ve kampanyaya g\xf6re sipariş bazında değişir."],["Komisyon KDV’si","%20 (sabit)","Komisyon %20 KDV’ye tabi bir hizmet bedelidir; bu komisyon KDV’si \xf6denecek KDV’nizden d\xfcş\xfcl\xfcr (indirilir) — net k\xe2ra etkisi br\xfct komisyon kadar değildir."],["Platform Hizmet Bedeli (standart)","10,99 + KDV = 13,19 TL","Her sipariş i\xe7in sabit kesinti; değişmedi."],["Platform Hizmet Bedeli (Bug\xfcn Kargoda)","4,99 + KDV = 5,99 TL","15 Haziran 2026’dan itibaren indirimli oran (\xf6ncesinde 6,99 + KDV = 8,39 TL)."],["Kargo","Desiye g\xf6re değişir","\xdcr\xfcn\xfcn desi/ağırlığına ve anlaşmalı kargo barem fiyatına g\xf6re hesaplanır."],["Satış KDV’si","\xdcr\xfcn\xfcn ger\xe7ek oranı","Satış fiyatına dahildir; \xfcr\xfcn\xfcn kendi KDV oranından (\xf6rn. %1, %10, %20) hesaplanır."],["Stopaj","%1","KDV hari\xe7 satış tutarının %1’i; gelir vergisi peşin kesintisi (tevkifat)."]],note:"Komisyon oranı kategoriye ve kampanyaya g\xf6re sipariş bazında değişir; aynı \xfcr\xfcn i\xe7in bile farklı siparişlerde farklı oran uygulanabilir. Kendi \xfcr\xfcn\xfcn\xfcz\xfcn kesin oranı i\xe7in yukarıdaki hesaplayıcıyı kullanın."},(0,i(77067).w)({platform:"trendyol",heading:"\xd6rnek: 299 TL’lik \xdcr\xfcnde Adım Adım Net K\xe2r",intro:"Aşağıdaki \xf6rnek %15 komisyon, 80 TL \xfcr\xfcn maliyeti ve 12 TL kargo varsayımıyla, standart (Bug\xfcn Kargoda olmayan) bir Trendyol siparişi i\xe7indir. Kendi oranlarınızı girdiğinizde sonu\xe7 değişir.",salePrice:299,commissionRate:15,cost:80,cargoPrice:12,vatRate:20,sameDay:!1,rateDateMs:Date.UTC(2026,5,16)}),{type:"pitfalls",heading:"K\xe2rınızı Sessizce Yiyen 5 Kalem",intro:"Aşağıdaki kalemler hesaplamada en sık atlanan ve satıcıları zarara s\xfcr\xfckleyen tuzaklardır.",items:[{title:"Komisyonun KDV etkisini atlamak",body:"Komisyon %20 KDV’ye tabidir; panel bu komisyon KDV’sini hesaplayıp \xf6denecek KDV’den d\xfcşer. Komisyonun KDV etkisini g\xf6z ardı etmek net k\xe2rı yanlış g\xf6sterir."},{title:"Stopajı hesaba katmamak",body:"Her satıştan KDV hari\xe7 tutarın %1’i stopaj olarak kesilir. K\xfc\xe7\xfck g\xf6r\xfcn\xfcr ama d\xfcş\xfck marjlı \xfcr\xfcnlerde net k\xe2rın \xf6nemli bir kısmını alır."},{title:"Platform hizmet bedelini yok saymak",body:"Sipariş başına sabit 13,19 TL (veya Bug\xfcn Kargoda’da 5,99 TL) d\xfcş\xfck fiyatlı \xfcr\xfcnlerde marjı eritir. 50 TL’lik bir \xfcr\xfcnde bu tek başına satışın d\xf6rtte birine yakındır."},{title:"İade ve kargo kayıplarını g\xf6z ardı etmek",body:"İade edilen siparişlerde kargo ve operasyon maliyeti kalır ama satış geliri geri d\xf6ner. Y\xfcksek iade oranlı kategorilerde ger\xe7ek k\xe2rınız hesapladığınızdan d\xfcş\xfckt\xfcr."},{title:"Ciroyu k\xe2r sanmak",body:"Aylık 100.000 TL ciro, 100.000 TL kazan\xe7 değildir. Maliyet ve kesintiler d\xfcş\xfclmeden yapılan b\xfcy\xfcme, \xe7oğu zaman zararı b\xfcy\xfctmekten başka işe yaramaz."}]},{type:"prose",heading:"KDV, Stopaj ve Platform Bedelinin Teknik Detayı",paragraphs:["KDV hesaplamasında kritik bir ayrım vardır: satış KDV’si, maliyet KDV’si ve stopaj matrahı \xfcr\xfcn\xfcn ger\xe7ek KDV oranından hesaplanır. Yani gıda gibi %1, bazı \xfcr\xfcnlerde %10, \xe7oğu \xfcr\xfcnde %20. Buna karşılık komisyon, kargo ve platform hizmet bedelinin KDV’si her zaman sabit %20’dir; \xe7\xfcnk\xfc bunlar pazaryerinin size kestiği hizmet bedelleridir, \xfcr\xfcn\xfcn kendi KDV oranıyla ilgisi yoktur. “Her şey %20” varsayımı, d\xfcş\xfck KDV’li \xfcr\xfcnlerde \xf6denecek KDV’yi yanlış hesaplatır.","\xd6denecek KDV, satış KDV’nizden indirebileceğiniz KDV’lerin (komisyon, kargo, platform bedeli ve \xfcr\xfcn maliyeti KDV’leri) d\xfcş\xfclmesiyle bulunur. Devlete net olarak yatırdığınız tutar budur ve net k\xe2r form\xfcl\xfcnde ayrı bir kalem olarak yer alır.","Stopaj ise gelir vergisinin kaynakta peşin kesilmesidir. Matrahı KDV hari\xe7 satış tutarıdır: 299 TL’lik bir satışta (KDV %20 ise) stopaj = 299 / 1,20 \xd7 0,01 ≈ 2,49 TL olur. Bu tutar yıl sonunda gelir vergisi beyannamenizde mahsup edilir; yani kalıcı bir gider değil, peşin \xf6denmiş vergidir — ama nakit akışınızı ve sipariş başı net k\xe2rınızı anlık olarak d\xfcş\xfcr\xfcr.","Platform hizmet bedeli (PHB) tarafında 2026’da \xf6nemli bir değişiklik var: “Bug\xfcn Kargoda” (SameDayShipping) etiketli siparişlerin indirimli PHB’si 15 Haziran 2026’dan itibaren 6,99 TL’den 4,99 TL’ye (KDV dahil 8,39 → 5,99) d\xfcşt\xfc. Standart 10,99 TL (KDV dahil 13,19) oran değişmedi. Bu indirim yalnızca Trendyol’un Bug\xfcn Kargoda oranı i\xe7indir; fiziksel kargo tarihine değil, siparişin Bug\xfcn Kargoda tipine bağlıdır."]},{type:"comparison",heading:"Trendyol’u Diğer Pazaryerleriyle Karşılaştırın",intro:"Aynı \xfcr\xfcn\xfc farklı pazaryerlerinde satıyorsanız kesinti yapısı değişir. Her platformun kendi k\xe2r hesaplayıcısıyla net k\xe2rınızı ayrı ayrı g\xf6r\xfcn.",rows:[{platform:"Hepsiburada",note:"Sabit Marketplace HB + işlem bedeli kesilir; “bug\xfcn kargoda” indirimi yoktur.",href:"/hepsiburada-kar-hesaplama"},{platform:"N11",note:"Platform bedeli y\xfczde bazlıdır: pazarlama (%1) + pazaryeri hizmet bedeli (%0,67).",href:"/n11-kar-hesaplama"},{platform:"Amazon",note:"Ayrı bir platform hizmet bedeli yoktur; ana kesinti referral (komisyon) \xfccretidir.",href:"/amazon-turkiye-kar-hesaplama"}]}]},t={platform:"trendyol",name:"Trendyol",slug:"trendyol-kar-hesaplama",color:"#f27a1a",heroSubtitle:"Komisyon, kargo, KDV ve stopaj dahil ger\xe7ek net k\xe2rınızı anında hesaplayın.",ctaText:"Trendyol mağazanızı bağlayın, sipariş ve hakediş verilerinizi otomatik analiz edin.",formulaLines:(0,r.jsxs)(r.Fragment,{children:["Net K\xe2r = Satış Tutarı",(0,r.jsx)("br",{}),"\xa0\xa0- Komisyon (Satış \xd7 Komisyon Oranı)",(0,r.jsx)("br",{}),"\xa0\xa0- Kargo Maliyeti (Desi barem fiyatı)",(0,r.jsx)("br",{}),"\xa0\xa0- Platform Hizmet Bedeli (5,99 TL veya 13,19 TL)",(0,r.jsx)("br",{}),"\xa0\xa0- \xdcr\xfcn Maliyeti (Tedarik + Ambalaj)",(0,r.jsx)("br",{}),"\xa0\xa0- \xd6denecek KDV (Satış KDV - Gider KDV'leri)",(0,r.jsx)("br",{}),"\xa0\xa0- Stopaj (Satış / 1.20 \xd7 0.01)"]}),formulaNote:(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("strong",{style:{color:"inherit"},children:"\xd6nemli:"})," Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ",(0,r.jsx)("strong",{style:{color:"inherit"},children:"ger\xe7ek KDV oranı"})," \xfczerinden hesaplanır (\xf6r. %1, %10, %20). Trendyol'un kendi hizmet bedelleri (komisyon, kargo, platform hizmet bedeli) ise hizmet niteliğinde olduğundan %20 KDV ile hesaplanır."]}),faq:[{q:"Trendyol k\xe2r hesaplama nasıl yapılır?",a:"Trendyol'da k\xe2r hesaplamak i\xe7in satış fiyatından komisyon, kargo maliyeti, platform hizmet bedeli, \xfcr\xfcn maliyeti, KDV ve stopaj d\xfcş\xfclmelidir. Form\xfcl: Net K\xe2r = Satış Tutarı - Komisyon - Kargo - Platform HB - Maliyet - \xd6denecek KDV - Stopaj. NİTRU k\xe2r hesaplayıcı bu hesaplamayı otomatik yapar."},{q:"Trendyol komisyon oranları ne kadar?",a:"Trendyol komisyon oranları kategoriye g\xf6re %5 ile %25 arasında değişir. Elektronik \xfcr\xfcnlerde %8-12, giyimde %18-22, kozmetikte %15-20 civarındadır. Kesin oran \xfcr\xfcn kategorinize bağlıdır."},{q:"Trendyol stopaj nedir ve nasıl hesaplanır?",a:"Stopaj, devletin satıcıdan peşin aldığı gelir vergisi avansıdır. Oranı KDV hari\xe7 satış tutarının %1'idir. Form\xfcl: Stopaj = Satış Tutarı / 1.20 \xd7 0.01. Yıllık gelir vergisi beyannamenizden mahsup edilir."},{q:"Trendyol KDV hesaplaması nasıl yapılır?",a:"KDV, \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden hesaplanır: satış ve maliyet KDV'si \xfcr\xfcn\xfcn oranıyla (\xf6r. %1, %10, %20), Trendyol'un komisyon/kargo/platform hizmet bedeli KDV'si ise %20 ile hesaplanır. \xd6denecek KDV = Satış KDV − Gider KDV'leri. \xdcr\xfcn\xfcn KDV oranı NİTRU panelinde \xdcr\xfcn Merkezi'nden d\xfczenlenebilir."},{q:"Platform hizmet bedeli nedir?",a:"Trendyol her siparişten platform hizmet bedeli keser. Aynı g\xfcn kargolarda 5,99 TL (KDV dahil, 15 Haziran 2026'dan itibaren; \xf6ncesinde 8,39 TL), normal kargolarda 13,19 TL (KDV dahil) \xfccret uygulanır."},{q:"Trendyol'da desi hesaplama nasıl yapılır?",a:"Desi ağırlığı = En (cm) \xd7 Boy (cm) \xd7 Y\xfckseklik (cm) / 3000 form\xfcl\xfcyle hesaplanır. Kargo firmaları ger\xe7ek ağırlık ve desi ağırlığından b\xfcy\xfck olanı baz alır."},{q:"NİTRU k\xe2r hesaplayıcı \xfccretsiz mi?",a:"Evet, NİTRU k\xe2r hesaplayıcısını \xfccretsiz kullanabilirsiniz. Kayıt olmadan tek siparişlik hesaplama yapabilirsiniz. Mağazanızı bağlayarak t\xfcm siparişlerinizin otomatik k\xe2r analizini g\xf6rmek i\xe7in \xfccretsiz kayıt olun."},{q:"Hangi pazaryerleri destekleniyor?",a:"NİTRU, Trendyol, Hepsiburada, Amazon, N11, \xc7i\xe7eksepeti ve Pazarama olmak \xfczere 6 pazaryerini destekler. T\xfcm platformlardaki mağazalarınızı tek panelden y\xf6netebilirsiniz."},{q:"Trendyol'da satıştan elime ne kadar kalır?",a:"Elinize kalan net k\xe2r = Satış - Komisyon - Kargo - Platform Hizmet Bedeli - \xdcr\xfcn Maliyeti - \xd6denecek KDV - Stopaj. Komisyon kategoriye g\xf6re değiştiği ve \xfcr\xfcn maliyetiniz size \xf6zel olduğu i\xe7in kesin tutar her satışta farklıdır. Yukarıdaki hesaplayıcıya satış fiyatınızı, \xfcr\xfcn maliyetinizi ve kategori komisyon oranınızı girerek elinize kalacak net tutarı g\xf6rebilirsiniz."},{q:"Trendyol komisyonu KDV dahil mi hesaplanır?",a:"Komisyon, \xfcr\xfcn\xfcn satış fiyatı \xfczerinden hesaplanır. Trendyol komisyonu bir hizmet bedeli olduğu i\xe7in komisyon tutarına ayrıca %20 KDV eklenir; bu komisyon KDV'si \xf6denecek KDV hesabınızda indirilebilir. NİTRU hesaplayıcı komisyon KDV'sini otomatik dikkate alır."},{q:"Trendyol k\xe2r marjı ne kadar olmalı?",a:"Sağlıklı k\xe2r marjı kategoriye ve rekabete g\xf6re değişir; pazaryeri satıcıları i\xe7in genelde satış fiyatının %15-30'u arası net marj s\xfcrd\xfcr\xfclebilir kabul edilir. Komisyonu y\xfcksek kategorilerde maliyet ve kargo optimizasyonu marjı korumak i\xe7in kritiktir. \xd6nemli olan ciro değil, sipariş başına net k\xe2rınızdır."},{q:"Trendyol aynı g\xfcn kargo platform hizmet bedeli ne kadar?",a:"Aynı g\xfcn kargo (SameDayShipping) siparişlerinde platform hizmet bedeli 15 Haziran 2026'dan itibaren 5,99 TL (KDV dahil); \xf6ncesinde 8,39 TL idi. Standart kargolarda platform hizmet bedeli 13,19 TL (KDV dahil) olarak uygulanır."},{q:"Trendyol komisyonu ne zaman kesilir?",a:"Komisyon, satış anında değil hakediş (\xf6deme) s\xfcrecinde mahsup edilir. Trendyol satış bedelini komisyon, kargo ve diğer kesintileri d\xfcşt\xfckten sonra hakediş tarihinde hesabınıza aktarır. NİTRU panelinde hakediş kalemlerini sipariş bazında takip edebilirsiniz."},{q:"Stopaj ne zaman ve nasıl geri alınır?",a:"Stopaj, KDV hari\xe7 satış tutarı \xfczerinden peşin kesilen %1'lik gelir vergisi avansıdır. Yıl sonunda verdiğiniz gelir vergisi beyannamesinde, yıl i\xe7inde kesilen toplam stopaj hesaplanan vergiden mahsup edilir; fazlası iade alınabilir. Yani stopaj kalıcı gider değil, peşin \xf6denen vergidir."},{q:"Trendyol'da KDV oranı nasıl belirlenir?",a:"KDV oranı \xfcr\xfcn\xfcn kendi yasal oranıdır (\xf6r. bazı gıda ve kitaplarda %1 veya %10, \xe7oğu \xfcr\xfcnde %20). Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek oranıyla; komisyon, kargo ve platform hizmet bedeli KDV'si ise hizmet niteliğinde olduğundan %20 ile hesaplanır. NİTRU panelinde her \xfcr\xfcn\xfcn KDV oranını \xdcr\xfcn Merkezi'nden d\xfczenleyebilirsiniz."},{q:"Desi nedir ve kargo \xfccretini nasıl etkiler?",a:"Desi, kolinin hacimsel ağırlığıdır: En \xd7 Boy \xd7 Y\xfckseklik (cm) / 3000. Kargo firması ger\xe7ek ağırlık ile desi ağırlığından b\xfcy\xfck olanı baz alır ve barem fiyatını buna g\xf6re uygular. B\xfcy\xfck ama hafif \xfcr\xfcnlerde desi ger\xe7ek ağırlıktan y\xfcksek \xe7ıkar ve kargo maliyetini artırır."},{q:"Trendyol k\xe2r hesabında en \xe7ok unutulan giderler hangileri?",a:"En sık atlanan kalemler: platform hizmet bedeli, %1 stopaj, komisyon \xfczerindeki %20 KDV, kargo desi farkı, ambalaj/paketleme maliyeti ve iade kaynaklı kayıplardır. Bu kalemler atlandığında \xfcr\xfcn k\xe2rlı g\xf6r\xfcnse de ger\xe7ekte zarar ettirebilir. NİTRU hesaplayıcı t\xfcm bu kalemleri otomatik dahil eder."},{q:"Trendyol k\xe2r hesaplamayı Excel ile mi yapmalıyım?",a:"Excel ile yapılabilir; ancak komisyon oranları, platform hizmet bedeli ve KDV kuralları değiştiği i\xe7in form\xfclleri g\xfcncel tutmak zordur. NİTRU hesaplayıcı g\xfcncel oran ve kuralları kullanır; mağazanızı bağladığınızda ger\xe7ek sipariş ve hakediş verinizle her siparişin net k\xe2rını otomatik hesaplar."},{q:"NİTRU k\xe2r hesaplayıcı ger\xe7ek sipariş verisiyle mi \xe7alışır?",a:"Kayıt olmadan tek siparişlik manuel hesaplama yapabilirsiniz. Trendyol mağazanızı bağladığınızda ise sipariş ve hakediş verileriniz otomatik \xe7ekilir; her siparişin ger\xe7ek komisyonu, kargosu ve kesintileriyle net k\xe2rı tek tek ve toplu raporlanır."},{q:"Trendyol'da ciro ile net k\xe2r arasındaki fark nedir?",a:"Ciro toplam satış tutarınızdır; net k\xe2r ise t\xfcm kesintiler (komisyon, kargo, platform hizmet bedeli, maliyet, KDV, stopaj) d\xfcş\xfcld\xfckten sonra elinize kalan tutardır. Y\xfcksek ciro y\xfcksek k\xe2r anlamına gelmez — komisyonu ve maliyeti y\xfcksek \xfcr\xfcnlerde ciro b\xfcy\xfcrken net k\xe2r eriyebilir. Bu y\xfczden ciroyu değil sipariş başına net k\xe2rı izlemek gerekir."}],blogLinks:[{href:"/blog/trendyol-kar-hesaplama-rehberi",label:"K\xe2r Hesaplama Rehberi"},{href:"/blog/trendyol-net-kar-nasil-hesaplanir",label:"Net K\xe2r Nasıl Hesaplanır"},{href:"/blog/trendyol-komisyon-kdv-dahil-gercek-kesinti",label:"Komisyon + KDV Ger\xe7ek Kesinti"},{href:"/blog/eticaret-kdv-stopaj-rehberi",label:"KDV ve Stopaj Rehberi"},{href:"/blog/trendyol-kar-marji-nasil-artirilir",label:"K\xe2r Marjı Nasıl Artırılır"},{href:"/blog",label:"T\xfcm Blog Yazıları"}],content:l};function o(){return(0,r.jsx)(n.Z,{config:t})}}},function(a){a.O(0,[6669,5250,2406,6095,3897,9778,9952,7774,6676,9419,581,6972,8214,7447,3138,2971,8069,1744],function(){return a(a.s=85910)}),_N_E=a.O()}]);